// Lambda entry point (API Gateway HTTP API, payload format 2.0).
//
//   GET  /              signup page        GET /app.js   page script
//   POST /api/start     { email, turnstileToken? }  -> emails a 6-digit code
//   POST /api/verify    { email, code }             -> sets session cookie
//   POST /api/register  { firstName, lastName, companyName } (needs session)
//                       -> creates billing Customer, then aPersona signup
//   POST /api/resend    (needs session) -> resends the aPersona invitation
import { createHash, randomInt, randomUUID, timingSafeEqual } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { cfg } from './config.mjs';
import { store, underLimit } from './store.mjs';
import { sendVerificationCode } from './email.mjs';
import { signSession, readSession, hmac, COOKIE } from './session.mjs';
import { createBillingCustomer, apersonaSignup, apersonaResend, UpstreamError } from './upstream.mjs';

const PAGE = readFileSync(new URL('../public/index.html', import.meta.url), 'utf8');
const SCRIPT = readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
const LOGO = readFileSync(new URL('../public/logo.png', import.meta.url)).toString('base64');

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const normEmail = (e) => String(e || '').trim().toLowerCase();
const recordKey = (email) => `email#${email}`;

export async function handler(event) {
  const method = event.requestContext?.http?.method;
  const path = event.rawPath;
  try {
    if (method === 'GET' && (path === '/' || path === '/index.html')) return page();
    if (method === 'GET' && path === '/app.js') return asset(SCRIPT, 'text/javascript; charset=utf-8');
    if (method === 'GET' && path === '/logo.png') return binaryAsset(LOGO, 'image/png');
    if (method === 'POST' && path.startsWith('/api/')) {
      const body = parseBody(event);
      if (body === undefined) return json(400, { error: 'bad_request', message: 'Invalid request.' });
      switch (path) {
        case '/api/start': return await start(event, body);
        case '/api/verify': return await verify(event, body);
        case '/api/register': return await register(event, body);
        case '/api/resend': return await resend(event);
      }
    }
    return json(404, { error: 'not_found' });
  } catch (e) {
    console.error('unhandled', e);
    return json(500, { error: 'server_error', message: 'Something went wrong. Please try again.' });
  }
}

// ---------- Step 1: email -> code ----------

async function start(event, body) {
  const c = cfg();
  const email = normEmail(body.email);
  if (!EMAIL_RE.test(email) || email.length > 254) {
    return json(400, { error: 'invalid_email', message: 'Enter a valid email address.' });
  }

  const ip = event.requestContext?.http?.sourceIp || 'unknown';
  if (!(await underLimit('ip', ip, c.maxStartsPerIpPerHour, 3600e3))) return tooMany();

  if (process.env.TURNSTILE_SECRET || process.env.TURNSTILE_SECRET_SECRET_ID) {
    if (!(await turnstileOk(body.turnstileToken, ip))) {
      return json(400, { error: 'bot_check', message: 'Please complete the "I am human" check.' });
    }
  }

  const rec = await store().get(recordKey(email));
  if (rec?.codeSentAt && Date.now() - rec.codeSentAt < c.minResendMs) {
    return json(429, { error: 'wait', message: 'Please wait a few seconds before requesting another code.' });
  }
  if (!(await underLimit('email', email, c.maxSendsPerEmailPerHour, 3600e3))) return tooMany();

  const code = String(randomInt(0, 1_000_000)).padStart(6, '0');
  await store().update(recordKey(email), {
    email,
    codeHash: await hmac(`${email}:${code}`),
    codeExpires: Date.now() + c.codeTtlMs,
    codeAttempts: 0,
    codeSentAt: Date.now(),
    createdAt: rec?.createdAt ?? new Date().toISOString(),
  });
  await sendVerificationCode(email, code);
  return json(200, { ok: true });
}

// ---------- Step 2: code -> verified session ----------

async function verify(event, body) {
  const c = cfg();
  const email = normEmail(body.email);
  const code = String(body.code || '').replace(/\D/g, '');
  const rec = await store().get(recordKey(email));

  if (!rec?.codeHash || rec.codeExpires < Date.now()) {
    return json(400, { error: 'code_expired', message: 'That code has expired. Request a new one.' });
  }
  if (rec.codeAttempts >= c.maxCodeAttempts) {
    return json(400, { error: 'too_many_attempts', message: 'Too many wrong codes. Request a new one.' });
  }
  await store().update(recordKey(email), { codeAttempts: (rec.codeAttempts || 0) + 1 });

  const expected = Buffer.from(rec.codeHash);
  const given = Buffer.from(await hmac(`${email}:${code}`));
  if (code.length !== 6 || expected.length !== given.length || !timingSafeEqual(expected, given)) {
    const left = c.maxCodeAttempts - (rec.codeAttempts + 1);
    return json(400, { error: 'wrong_code', message: left > 0 ? 'That code is not right. Check the email and try again.' : 'Too many wrong codes. Request a new one.' });
  }

  const verifiedAt = new Date().toISOString();
  const verificationId = `ev_${randomUUID()}`;
  await store().update(recordKey(email), {
    verifiedAt, verificationId, codeHash: null, codeExpires: null, codeAttempts: null,
  });

  const token = await signSession({ email, vid: verificationId, exp: Date.now() + c.sessionTtlMs });
  return json(200, {
    ok: true,
    // Ownership is proven now, so it's fine to say whether this email already signed up.
    alreadyRegistered: Boolean(rec.signupStatus),
    signupStatus: rec.signupStatus || null,
    loginUrl: rec.loginUrl || null,
  }, [cookie(token, c.sessionTtlMs / 1000)]);
}

// ---------- Step 3: profile -> billing Customer -> aPersona signup ----------

async function register(event, body) {
  const session = await sessionFrom(event);
  if (!session) return json(401, { error: 'not_verified', message: 'Your session expired. Start again with your email.' });

  const key = recordKey(session.email);
  const rec = await store().get(key);
  if (!rec || rec.verificationId !== session.vid) {
    return json(401, { error: 'not_verified', message: 'Your session expired. Start again with your email.' });
  }

  const profile = {};
  for (const [field, label] of [['firstName', 'First name'], ['lastName', 'Last name'], ['companyName', 'Company name']]) {
    const v = String(body[field] ?? '').trim();
    if (!v) return json(400, { error: 'validation_error', field, message: `${label} is required.` });
    if (v.length > 256) return json(400, { error: 'validation_error', field, message: `${label} is too long.` });
    profile[field] = v;
  }

  if (!(await store().lock(key, 60e3))) {
    return json(409, { error: 'in_progress', message: 'Your signup is already being processed. Give it a few seconds.' });
  }
  try {
    // 1) Billing Customer — created once per email, then reused on every retry.
    let billingCustomerId = rec.billingCustomerId;
    if (!billingCustomerId) {
      const slug = rec.slug || slugFor(session.email);
      await store().update(key, { slug });
      billingCustomerId = await createBillingCustomer(session.email, slug);
      await store().update(key, { billingCustomerId, billingCustomerCreatedAt: new Date().toISOString() });
      console.log('billing customer ready', { slug, billingCustomerId });
    }

    // 2) aPersona Identity signup (idempotent for the same email + customer id).
    const res = await apersonaSignup({
      signupType: 'tenant',
      adminEmail: session.email,
      adminFirstName: profile.firstName,
      adminLastName: profile.lastName,
      companyName: profile.companyName,
      billingCustomerId,
      emailVerification: { verifiedAt: rec.verifiedAt, verificationId: rec.verificationId },
    });

    if (res.status === 201 || res.status === 200) {
      await store().update(key, {
        signupStatus: res.body.status, loginUrl: res.body.loginUrl, ...profile,
        signedUpAt: rec.signedUpAt ?? new Date().toISOString(),
      });
      return json(200, {
        ok: true, status: res.body.status, loginUrl: res.body.loginUrl, alreadyRegistered: res.status === 200,
      });
    }

    const code = res.body?.errorCode;
    console.warn('apersona signup refused', { status: res.status, errorCode: code, billingCustomerId });
    if (res.status === 409 && code === 'email_in_use') {
      return json(409, { error: 'email_in_use', loginUrl: cfg().adminPortalUrl,
        message: 'This email already has an Admin Portal account. Sign in instead.' });
    }
    if (res.status === 409 && code === 'signup_conflict') {
      return json(409, { error: 'signup_conflict',
        message: 'This email is already registered under a different account. Please contact support.' });
    }
    if (res.status === 400 && code === 'validation_error') {
      return json(400, { error: 'validation_error', field: res.body.field, message: res.body.message });
    }
    return json(502, { error: 'upstream', message: 'We could not finish your signup right now. Please try again in a minute.' });
  } catch (e) {
    if (e instanceof UpstreamError) {
      console.error('upstream failure', e.message);
      return json(502, { error: 'upstream', message: 'We could not finish your signup right now. Please try again in a minute.' });
    }
    throw e;
  } finally {
    await store().unlock(key);
  }
}

// ---------- Resend the aPersona invitation ----------

async function resend(event) {
  const session = await sessionFrom(event);
  if (!session) return json(401, { error: 'not_verified', message: 'Your session expired. Start again with your email.' });
  if (!(await underLimit('resend', session.email, 3, 3600e3))) return tooMany();

  const res = await apersonaResend(session.email);
  if (res.status === 200) return json(200, { ok: true });
  const code = res.body?.errorCode;
  const messages = {
    signup_complete: 'Your setup is already finished. Sign in, or use "Forgot password" on the login page.',
    signup_in_progress: 'You have already signed in and started setup. Sign in to continue.',
    signup_not_found: 'We could not find an open signup for this email.',
  };
  if (messages[code]) return json(409, { error: code, message: messages[code], loginUrl: cfg().adminPortalUrl });
  console.warn('resend refused', res.status, res.body?.errorCode);
  return json(502, { error: 'upstream', message: 'We could not resend the invitation right now. Please try again shortly.' });
}

// ---------- helpers ----------

// Deterministic per email, so a retried create reports "already exists" instead of
// making a second customer. Doesn't put the email itself in a platform-wide identifier.
function slugFor(email) {
  return `aps-${createHash('sha256').update(email).digest('hex').slice(0, 24)}`;
}

async function sessionFrom(event) {
  const raw = (event.cookies || []).find((c) => c.startsWith(`${COOKIE}=`));
  return raw ? readSession(raw.slice(COOKIE.length + 1)) : null;
}

async function turnstileOk(token, ip) {
  if (!token) return false;
  const { getSecret } = await import('./secrets.mjs');
  const res = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
    method: 'POST',
    body: new URLSearchParams({ secret: await getSecret('TURNSTILE_SECRET'), response: token, remoteip: ip }),
    signal: AbortSignal.timeout(5000),
  }).catch(() => null);
  return Boolean(res?.ok && (await res.json()).success);
}

function parseBody(event) {
  if (!event.body) return {};
  try {
    const raw = event.isBase64Encoded ? Buffer.from(event.body, 'base64').toString() : event.body;
    if (raw.length > 4096) return undefined;
    const v = JSON.parse(raw);
    return v && typeof v === 'object' && !Array.isArray(v) ? v : undefined;
  } catch { return undefined; }
}

function cookie(token, maxAge) {
  const secure = cfg().cookieSecure ? '; Secure' : '';
  return `${COOKIE}=${token}; Max-Age=${Math.floor(maxAge)}; Path=/api; HttpOnly; SameSite=Strict${secure}`;
}

const securityHeaders = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'Strict-Transport-Security': 'max-age=31536000',
};

function json(statusCode, body, cookies) {
  return {
    statusCode,
    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...securityHeaders },
    body: JSON.stringify(body),
    ...(cookies ? { cookies } : {}),
  };
}

const tooMany = () => json(429, { error: 'rate_limited', message: 'Too many attempts. Please try again later.' });

function page() {
  const html = PAGE.replace('{{TURNSTILE_SITE_KEY}}', escapeAttr(cfg().turnstileSiteKey))
    .replaceAll('{{PRODUCT_NAME}}', escapeAttr(cfg().productName));
  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-cache',
      'X-Frame-Options': 'DENY',
      'Content-Security-Policy':
        "default-src 'self'; script-src 'self' https://challenges.cloudflare.com; " +
        "frame-src https://challenges.cloudflare.com; style-src 'self' 'unsafe-inline'; " +
        "img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
      ...securityHeaders,
    },
    body: html,
  };
}

const asset = (body, type) => ({
  statusCode: 200, headers: { 'Content-Type': type, 'Cache-Control': 'no-cache', ...securityHeaders }, body,
});

// Static binary (API Gateway HTTP API decodes base64 when isBase64Encoded is set). Immutable, so cache for a day.
const binaryAsset = (base64, type) => ({
  statusCode: 200, isBase64Encoded: true, body: base64,
  headers: { 'Content-Type': type, 'Cache-Control': 'public, max-age=86400', ...securityHeaders },
});

const escapeAttr = (s) => String(s).replace(/[&<>"']/g, (ch) => `&#${ch.charCodeAt(0)};`);
