// All settings come from environment variables (set in template.yaml).
// Read lazily so tests can set process.env before the first request.
const env = process.env;

export function cfg() {
  return {
    // Licensing server (APL)
    licensingBase: required('APL_BASE'),
    installationUrl: required('INST_URL'),
    itServiceOrgId: Number(env.IT_SERVICE_ORG_ID || 640),

    // aPersona Identity signup API
    signupBase: env.SIGNUP_BASE || 'https://api.adminportal.id.weaveai.net',
    adminPortalUrl: env.ADMIN_PORTAL_URL || 'https://adminportal.id.weaveai.net',

    // Storage and email
    store: env.STORE || 'dynamodb',            // 'dynamodb' | 'memory' (tests/local only)
    tableName: env.TABLE_NAME || 'apersona-signup',
    emailTransport: env.EMAIL_TRANSPORT || 'ses', // 'ses' | 'memory' | 'console' (tests/local only)
    fromEmail: env.FROM_EMAIL || '',
    productName: env.PRODUCT_NAME || 'aPersona Identity',

    // Optional Cloudflare Turnstile bot check on the first step
    turnstileSiteKey: env.TURNSTILE_SITE_KEY || '',

    // Cookie: Secure everywhere except plain-http local dev
    cookieSecure: env.COOKIE_INSECURE !== 'true',

    // Limits
    codeTtlMs: 10 * 60 * 1000,
    maxCodeAttempts: 5,
    minResendMs: 30 * 1000,
    maxSendsPerEmailPerHour: 5,
    maxStartsPerIpPerHour: 20,
    sessionTtlMs: 30 * 60 * 1000,
    upstreamTimeoutMs: 10 * 1000,
  };
}

function required(name) {
  const v = env[name];
  if (!v) throw new Error(`Missing required environment variable ${name}`);
  return v.replace(/\/+$/, '');
}
