// Secrets come from AWS Secrets Manager, cached for 5 minutes per container.
//
// For each secret you set ONE of:
//   <NAME>            the value itself (local dev / tests only)
//   <NAME>_SECRET_ID  a Secrets Manager id; append "#path" if the secret is JSON.
//                     The path is dot-separated; a segment may pick an array entry by
//                     a property, e.g. "apersona/signup/apikey#keys[id=launch].key"
const cache = new Map();
let client;

export function pickField(obj, path) {
  for (const seg of path.split('.')) {
    const m = /^([^[]*)(?:\[(\w+)=([^\]]+)\])?$/.exec(seg);
    if (!m) throw new Error(`Bad secret field path ${path}`);
    if (m[1]) obj = obj?.[m[1]];
    if (m[2]) obj = Array.isArray(obj) ? obj.find((e) => String(e?.[m[2]]) === m[3]) : undefined;
  }
  return obj;
}

export async function getSecret(name) {
  if (process.env[name]) return process.env[name];

  const ref = process.env[`${name}_SECRET_ID`];
  if (!ref) throw new Error(`Set ${name}_SECRET_ID (or ${name} for local dev)`);

  const hit = cache.get(ref);
  if (hit && hit.expires > Date.now()) return hit.value;

  const { SecretsManagerClient, GetSecretValueCommand } = await import('@aws-sdk/client-secrets-manager');
  client ??= new SecretsManagerClient({});
  const [secretId, field] = ref.split('#');
  const out = await client.send(new GetSecretValueCommand({ SecretId: secretId }));

  let value = out.SecretString;
  if (field) value = pickField(JSON.parse(value), field);
  if (!value) throw new Error(`Secret ${ref} is empty`);

  cache.set(ref, { value, expires: Date.now() + 5 * 60 * 1000 });
  return value;
}
