// Clients for the licensing server and the aPersona Identity signup API.
import { cfg } from './config.mjs';
import { getSecret } from './secrets.mjs';

export class UpstreamError extends Error {
  constructor(service, status, body) {
    super(`${service} returned ${status}: ${JSON.stringify(body)?.slice(0, 300)}`);
    this.service = service; this.status = status; this.body = body;
  }
}

async function call(method, url, headers, body) {
  let res;
  try {
    res = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...headers },
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(cfg().upstreamTimeoutMs),
    });
  } catch (e) {
    return { status: 0, ok: false, body: { error: e.name, message: e.message } }; // network / timeout
  }
  const text = await res.text();
  let parsed; try { parsed = text ? JSON.parse(text) : null; } catch { parsed = { raw: text.slice(0, 500) }; }
  return { status: res.status, ok: res.ok, body: parsed };
}

// ---------- Licensing server ----------

async function licensingHeaders() {
  return { 'X-Aplicense-Admin-Key': await getSecret('LICENSING_API_KEY') };
}

/**
 * Creates the billing Customer with the minimal fields plus our own slug.
 * Slugs are unique platform-wide, so the create is not safe to blindly retry;
 * a deterministic slug turns "already exists" into "find the one we made".
 */
export async function createBillingCustomer(email, slug) {
  const c = cfg();
  const res = await call('POST', `${c.licensingBase}/license/api/v1/customers`, await licensingHeaders(), {
    url: c.installationUrl,
    it_service_org_id: c.itServiceOrgId,
    name: email,
    billing_email: email,
    slug,
  });
  if (res.ok && Number.isInteger(res.body?.id)) return res.body.id;

  if (res.status === 400 && /already exists/i.test(res.body?.detail || '')) {
    const existing = await findCustomerBySlug(slug);
    if (existing) return existing;
  }
  throw new UpstreamError('licensing', res.status, res.body);
}

async function findCustomerBySlug(slug) {
  const c = cfg();
  // GET /v1/customers takes no filters; this only runs on the rare retry path.
  const res = await call('GET', `${c.licensingBase}/license/api/v1/customers`, await licensingHeaders());
  if (!res.ok) throw new UpstreamError('licensing', res.status, res.body);
  const list = Array.isArray(res.body) ? res.body : res.body?.items || res.body?.results || [];
  return list.find((x) => x.slug === slug)?.id ?? null;
}

// ---------- aPersona Identity signup ----------

async function signupHeaders() {
  return { 'X-Api-Key': await getSecret('SIGNUP_API_KEY') };
}

// POST /signup is idempotent: repeat on timeout, 5xx, or 503 invitation_failed.
export async function apersonaSignup(payload) {
  const url = `${cfg().signupBase}/signup`;
  const headers = await signupHeaders();
  let res;
  for (let attempt = 0; attempt < 3; attempt++) {
    if (attempt) await sleep(500 * 2 ** attempt);
    res = await call('POST', url, headers, payload);
    if (res.status !== 0 && res.status < 500) break;
  }
  return res;
}

export async function apersonaResend(adminEmail) {
  return call('POST', `${cfg().signupBase}/signup/resend-invitation`, await signupHeaders(), { adminEmail });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
