// Sends the 6-digit verification code. SES in AWS; 'memory'/'console' for tests and local dev.
import { cfg } from './config.mjs';

export const outbox = []; // filled by the 'memory' transport (tests read codes from here)
let ses;

export async function sendVerificationCode(to, code) {
  const c = cfg();
  const subject = `Your ${c.productName} verification code: ${code}`;
  const text =
    `Your ${c.productName} verification code is ${code}\n\n` +
    `Enter it on the signup page to confirm this email address. The code expires in 10 minutes.\n\n` +
    `If you didn't start a signup, you can ignore this email.`;

  if (c.emailTransport === 'memory') { outbox.push({ to, subject, text, code }); return; }
  if (c.emailTransport === 'console') { console.log(`[dev email] to=${to} code=${code}`); return; }

  if (!c.fromEmail) throw new Error('FROM_EMAIL is not set');
  const { SESv2Client, SendEmailCommand } = await import('@aws-sdk/client-sesv2');
  ses ??= new SESv2Client({});
  await ses.send(new SendEmailCommand({
    FromEmailAddress: c.fromEmail,
    Destination: { ToAddresses: [to] },
    Content: { Simple: {
      Subject: { Data: subject, Charset: 'UTF-8' },
      Body: { Text: { Data: text, Charset: 'UTF-8' } },
    } },
  }));
}
