// Persistence for signup records and rate-limit counters.
//
// One DynamoDB table, partition key "pk" (string), TTL attribute "ttl".
//   email#<normalized email>  -> the signup record (code hash, verification,
//                                billingCustomerId, signup status, ...)
//   rl#<scope>#<id>#<bucket>  -> rate-limit counter, expires on its own
import { cfg } from './config.mjs';

let impl;
export function store() {
  if (!impl) impl = cfg().store === 'memory' ? memoryStore() : dynamoStore(cfg().tableName);
  return impl;
}

// Fixed-window counter. Returns true while the caller is under the limit.
export async function underLimit(scope, id, limit, windowMs) {
  const bucket = Math.floor(Date.now() / windowMs);
  const count = await store().incr(`rl#${scope}#${id}#${bucket}`, Math.ceil((bucket + 2) * windowMs / 1000));
  return count <= limit;
}

function dynamoStore(TableName) {
  let doc;
  const client = async () => {
    if (doc) return doc;
    const { DynamoDBClient } = await import('@aws-sdk/client-dynamodb');
    const { DynamoDBDocumentClient } = await import('@aws-sdk/lib-dynamodb');
    doc = DynamoDBDocumentClient.from(new DynamoDBClient({}), {
      marshallOptions: { removeUndefinedValues: true },
    });
    return doc;
  };
  const lib = () => import('@aws-sdk/lib-dynamodb');

  return {
    async get(pk) {
      const { GetCommand } = await lib();
      const out = await (await client()).send(new GetCommand({ TableName, Key: { pk }, ConsistentRead: true }));
      return out.Item || null;
    },

    // Sets the given fields (null removes a field). Creates the item if missing.
    async update(pk, fields) {
      const { UpdateCommand } = await lib();
      const sets = [], removes = [], names = {}, values = {};
      Object.entries(fields).forEach(([k, v], i) => {
        names[`#f${i}`] = k;
        if (v === null) removes.push(`#f${i}`);
        else { sets.push(`#f${i} = :v${i}`); values[`:v${i}`] = v; }
      });
      if (!sets.length && !removes.length) return;
      const expr = [sets.length && `SET ${sets.join(', ')}`, removes.length && `REMOVE ${removes.join(', ')}`]
        .filter(Boolean).join(' ');
      await (await client()).send(new UpdateCommand({
        TableName, Key: { pk }, UpdateExpression: expr, ExpressionAttributeNames: names,
        ...(sets.length ? { ExpressionAttributeValues: values } : {}),
      }));
    },

    async incr(pk, ttl) {
      const { UpdateCommand } = await lib();
      const out = await (await client()).send(new UpdateCommand({
        TableName, Key: { pk },
        UpdateExpression: 'ADD #c :one SET #t = :ttl',
        ExpressionAttributeNames: { '#c': 'count', '#t': 'ttl' },
        ExpressionAttributeValues: { ':one': 1, ':ttl': ttl },
        ReturnValues: 'UPDATED_NEW',
      }));
      return out.Attributes.count;
    },

    // Short lease so two concurrent /register calls for one email can't both
    // create a billing customer.
    async lock(pk, ms) {
      const { UpdateCommand } = await lib();
      const now = Date.now();
      try {
        await (await client()).send(new UpdateCommand({
          TableName, Key: { pk },
          UpdateExpression: 'SET lockUntil = :until',
          ConditionExpression: 'attribute_not_exists(lockUntil) OR lockUntil < :now',
          ExpressionAttributeValues: { ':until': now + ms, ':now': now },
        }));
        return true;
      } catch (e) {
        if (e.name === 'ConditionalCheckFailedException') return false;
        throw e;
      }
    },

    async unlock(pk) {
      await this.update(pk, { lockUntil: null });
    },
  };
}

// In-process store for tests and local dev. Not for Lambda (no sharing between containers).
export function memoryStore() {
  const items = new Map();
  return {
    items,
    async get(pk) { const v = items.get(pk); return v ? structuredClone(v) : null; },
    async update(pk, fields) {
      const item = items.get(pk) || { pk };
      for (const [k, v] of Object.entries(fields)) v === null ? delete item[k] : (item[k] = v);
      items.set(pk, item);
    },
    async incr(pk, ttl) {
      const item = items.get(pk) || { pk, count: 0 };
      item.count += 1; item.ttl = ttl; items.set(pk, item);
      return item.count;
    },
    async lock(pk, ms) {
      const item = items.get(pk) || { pk };
      if (item.lockUntil && item.lockUntil >= Date.now()) return false;
      item.lockUntil = Date.now() + ms; items.set(pk, item);
      return true;
    },
    async unlock(pk) { await this.update(pk, { lockUntil: null }); },
  };
}
