// Small HMAC-signed session token, carried in an HttpOnly cookie after the email is verified.
import { createHmac, timingSafeEqual } from 'node:crypto';
import { getSecret } from './secrets.mjs';

export const COOKIE = 'aps_session';

const b64 = (buf) => Buffer.from(buf).toString('base64url');

export async function signSession(payload) {
  const body = b64(JSON.stringify(payload));
  return `${body}.${await mac(body)}`;
}

export async function readSession(token) {
  if (!token || !token.includes('.')) return null;
  const [body, sig] = token.split('.');
  const expected = Buffer.from(await mac(body));
  const given = Buffer.from(sig);
  if (expected.length !== given.length || !timingSafeEqual(expected, given)) return null;
  const payload = JSON.parse(Buffer.from(body, 'base64url').toString());
  return payload.exp > Date.now() ? payload : null;
}

// Also used to hash verification codes at rest.
export async function hmac(value) {
  return createHmac('sha256', await getSecret('SESSION_SECRET')).update(value).digest('base64url');
}

const mac = hmac;
